using var a=new LabScriptedAdapter();
using var b=new LabScriptedAdapter();
using var c=new LabController(a);
string id=c.Submit("SetLevel",30);
b.Emit(new LabCompletion(id,c.Session,"Completed"));
Console.WriteLine(c.Results[id]); // Pending
Console.WriteLine(a.Sent.Count); // 1
Console.WriteLine(b.Sent.Count); // 0
a.Emit(new LabCompletion(id,c.Session,"Completed"));
Console.WriteLine(c.Results[id]); // Completed
a.Emit(new LabCompletion(id,c.Session,"Completed"));
Console.WriteLine(c.Applied); // 1

using var a=new LabScriptedAdapter();
using var c=new LabController(a);
string old=c.Submit("QueryState",0);
c.Reconnect();
c.Authenticated=true; c.DeviceReady=true;
string current=c.Submit("QueryState",0);
a.Emit(new LabCompletion(current,1,"Completed"));
Console.WriteLine(c.Results[current]); // Pending
Console.WriteLine(c.Ignored); // 1
a.Emit(new LabCompletion(current,2,"Completed"));
Console.WriteLine(c.Results[current]); // Completed
